#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Source of truth for the UI translation catalogue.

The ENGLISH STRING IS THE KEY (see src/i18n.h). Add a language by adding its
code to LANGS and a column to CAT; run this to regenerate src/i18n_catalogue.h.
A blank translation is legal and means "not translated yet" -- tr() falls back
to English, so a partial column ships safely.

Terminology follows the established CAD vocabulary of each language rather than
a literal rendering: fillet is "Redondeo"/"Conge"/"Verrundung", not "relleno".
Spanish and Portuguese are LATIN AMERICAN / BRAZILIAN, matching where the users
asking for this actually are.
Chinese uses Simplified Chinese with standard CAD terminology.
"""
import os, sys

LANGS = ["es", "pt", "fr", "de", "it", "zh"]
LANG_NATIVE  = {"en":"English", "es":"Español", "pt":"Português",
                "fr":"Français", "de":"Deutsch", "it":"Italiano", "zh":"中文"}
LANG_ENGLISH = {"en":"English", "es":"Spanish", "pt":"Portuguese",
                "fr":"French", "de":"German", "it":"Italian", "zh":"Chinese"}

def _E_impl(en, es, pt, fr, de, it, zh=""):
    return (en, {"es":es, "pt":pt, "fr":fr, "de":de, "it":it, "zh":zh})

# Accept both 6 args (legacy) and 7 args (with Chinese)
def E(*args):
    if len(args) == 6:
        en, es, pt, fr, de, it = args
        return _E_impl(en, es, pt, fr, de, it, "")
    elif len(args) == 7:
        return _E_impl(*args)
    else:
        raise TypeError(f"E() takes 6 or 7 arguments, got {len(args)}")

